const $=s=>document.querySelector(s),state={user:null,project:null,portalData:null,stream:null,tab:'home',portal:location.pathname.startsWith('/portal')||location.pathname.startsWith('/c/')};
const statuses={NEW:'بانتظار تعيين مصمم',NEW_TASK:'مهمة جديدة',WAITING_FOR_DESIGNER:'بانتظار تعيين مصمم',IN_DESIGN:'قيد التنفيذ',WAITING_FOR_CLIENT:'بانتظار العميل',REVISION_REQUESTED:'طلب تعديل',APPROVED:'معتمد',COMPLETED:'مكتمل',CANCELLED:'ملغى'};const statusText={NEW:'بانتظار تعيين مصمم',NEW_TASK:'مهمة جديدة — ابدأ التنفيذ',WAITING_FOR_DESIGNER:'بانتظار بدء المصمم',IN_DESIGN:'جاري تجهيز التصميم',WAITING_FOR_CLIENT:'التصميم جاهز للمراجعة',REVISION_REQUESTED:'تم استلام ملاحظاتك',APPROVED:'تم اعتماد التصميم',COMPLETED:'تم إنجاز المشروع',CANCELLED:'المشروع متوقف'};
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const fmt=d=>d?new Date(d).toLocaleString('ar-SA',{dateStyle:'medium',timeStyle:'short'}):'—';const ago=d=>{const n=Math.max(0,Date.now()-new Date(d).getTime()),m=Math.floor(n/60000);return m<60?`منذ ${m||1} دقيقة`:m<1440?`منذ ${Math.floor(m/60)} ساعة`:`منذ ${Math.floor(m/1440)} يوم`};const badge=s=>`<span class="status status-${String(s).toLowerCase()}"><i></i>${statuses[s]||esc(s)}</span>`;
async function api(url,opt={}){const headers={...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opt.headers||{})};const r=await fetch(url,{...opt,headers,credentials:'same-origin'});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'حدث خطأ غير متوقع');return d}function toast(text,type=''){$('#toast')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="toast" class="toast ${type}">${esc(text)}</div>`);setTimeout(()=>$('#toast')?.remove(),3200)}function closeStream(){if(state.stream){state.stream.close();state.stream=null}if(state.syncTimer){clearInterval(state.syncTimer);state.syncTimer=null}}function openStream(url,handler){closeStream();let es,closed=false,timer;const connection={close(){closed=true;clearTimeout(timer);es?.close();if(state.stream===connection)state.stream=null}};const connect=()=>{if(closed)return;es=new EventSource(url);state.stream=connection;es.onmessage=e=>{try{const x=JSON.parse(e.data);if(x.type!=='connected')handler(x)}catch{}};es.onerror=()=>{es.close();if(!closed)timer=setTimeout(connect,2000)}};connect();return connection}
function login(){closeStream();document.body.innerHTML=`<main class="login"><form class="login-card" id="login-form"><div class="brand brand-large"><img class="brand-image" src="/brand-logo.png" alt="G.PACK"></div><span class="eyebrow">مساحة العمل الإبداعية</span><h1>مرحباً بك</h1><p class="muted">سجّل الدخول لإدارة مشاريعك ومتابعة التصميمات</p><div class="field"><label>البريد الإلكتروني أو رقم الجوال</label><input name="login" type="text" autocomplete="username" required placeholder="name@gpack.sa أو 0551234567"></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn btn-primary btn-block">تسجيل الدخول</button></form></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.email=b.login;const btn=e.target.querySelector('button');btn.disabled=true;btn.textContent='جار تسجيل الدخول...';try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify(b)});state.token=d.token||null;state.user=d.user;state.tab=state.user.role==='ADMIN'?'home':'designer';render()}catch(x){toast(x.message,'error');btn.disabled=false;btn.textContent='تسجيل الدخول'}}}
function getArabicDateString(){try{const d=new Date(),days=['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'],months=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];return`${days[d.getDay()]}، ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`}catch{return'—'}}
function projectThumbnail(p){if(p.thumbnail_id)return`<img src="/api/files/${p.thumbnail_id}" alt="${esc(p.name)}" class="project-thumb-img">`;return`<div class="project-thumb-placeholder"><svg viewBox="0 0 48 48" fill="none"><path d="M24 6L40 15L24 24L8 15L24 6Z" fill="#E8DFEE" stroke="#5A3D63" stroke-width="2" stroke-linejoin="round"/><path d="M8 15V33L24 42V24L8 15Z" fill="#DFCDE8" stroke="#5A3D63" stroke-width="2" stroke-linejoin="round"/><path d="M40 15V33L24 42V24L40 15Z" fill="#F4EEF8" stroke="#5A3D63" stroke-width="2" stroke-linejoin="round"/><path d="M24 24V42" stroke="#5A3D63" stroke-width="2"/><circle cx="24" cy="15" r="2.5" fill="#FFC42B"/></svg></div>`}
function projectStatusBadge(status){const map={NEW_TASK:{label:'مهمة جديدة',class:'status-new-task'},WAITING_FOR_DESIGNER:{label:'بانتظار المصمم',class:'status-waiting-designer'},IN_DESIGN:{label:'قيد التنفيذ',class:'status-in-design'},WAITING_FOR_CLIENT:{label:'بانتظار العميل',class:'status-waiting-client'},REVISION_REQUESTED:{label:'طلب تعديل',class:'status-revision'},APPROVED:{label:'معتمد',class:'status-approved'},COMPLETED:{label:'مكتمل',class:'status-completed'},CANCELLED:{label:'ملغى',class:'status-cancelled'}};const item=map[status]||{label:statuses[status]||status,class:'status-default'};return`<span class="status-pill ${item.class}">${item.label}</span>`}
async function render(){if(state.portal)return renderPortal();if(!state.user){try{state.user=(await api('/api/auth/me')).user}catch{login();return}}if(state.user.role==='DESIGNER'){try{const notifs=await api('/api/notifications');state.unreadCount=notifs.filter(n=>!n.read_at).length}catch{}}renderInternal()}
function renderInternal(){document.body.innerHTML=`<div class="internal-shell"><aside class="internal-sidebar"><div class="brand"><div class="brand-badge"><img class="brand-image" src="/brand-logo.png" alt="G.PACK"></div><span class="brand-name">G.PACK</span></div><div class="workspace-label">مساحة العمل</div><nav>${state.user.role==='ADMIN'?`<button data-tab="home"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg><span>نظرة عامة</span></button><button data-tab="projects"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg><span>المشاريع</span></button><button data-tab="clients"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg><span>العملاء</span></button><button data-tab="designers"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="8" r="5"/><path d="M20 21a8 8 0 1 0-16 0"/></svg><span>المصممون</span></button><button data-tab="activity"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg><span>النشاط</span></button>`:`<button data-tab="designer"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg><span>الرئيسية</span></button><button data-tab="projects"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg><span>تصاميمي</span></button><button data-tab="approved"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 15l-2 5 2-1 2 1-2-5"/><circle cx="12" cy="8" r="6"/><path d="m9 8 2 2 4-4"/></svg><span>المعتمدة</span></button><button data-tab="notifications"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/></svg><span>الإشعارات</span>${state.unreadCount?`<span class="nav-badge" id="nav-notif-count">${state.unreadCount}</span>`:''}</button><button data-tab="account"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="8" r="5"/><path d="M20 21a8 8 0 1 0-16 0"/></svg><span>حسابي</span></button>`}</nav><div class="sidebar-slogan"><span class="slogan-text">اصنع فرقك بقلم</span><div class="slogan-line"></div></div><div class="sidebar-bottom"><div class="user-avatar">${esc((state.user.name||'G').slice(0,1))}</div><div class="user-meta"><b>${esc(state.user.name)}</b><small>${state.user.role==='ADMIN'?'مدير النظام':'مصمم'}</small></div><button class="logout-button" onclick="logout()" aria-label="تسجيل الخروج" title="تسجيل الخروج"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" x2="9" y1="12" y2="12"/></svg></button></div></aside><main class="internal-main"><div class="top-nav-bar"><div class="top-nav-date"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect width="18" height="18" x="3" y="4" rx="2"/><line x1="16" x2="16" y1="2" y2="6"/><line x1="8" x2="8" y1="2" y2="6"/><line x1="3" x2="21" y1="10" y2="10"/></svg><span>${getArabicDateString()}</span></div><button class="top-notif-btn" onclick="state.tab='notifications';renderInternal()" aria-label="الإشعارات" title="الإشعارات"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/></svg>${state.unreadCount?'<span class="top-notif-dot"></span>':''}</button></div><div id="internal-view"></div></main></div>`;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.onclick=()=>{state.tab=b.dataset.tab;renderInternal()}});renderInternalView()}
async function renderInternalView(){const v=$('#internal-view');v.innerHTML='<div class="page-loading"><span></span><span></span><span></span></div>';try{if(state.user.role==='ADMIN'){if(state.tab==='home')return adminHome(v);if(state.tab==='projects')return internalProjects(v);if(state.tab==='clients')return clients(v);if(state.tab==='designers')return designers2(v);if(state.tab==='activity')return activityCenter(v)}else{if(state.tab==='designer')return designerHome(v);if(state.tab==='projects'||state.tab==='waiting')return designerQueue(v);if(state.tab==='approved')return approvedGallery(v);if(state.tab==='notifications')return notificationsPage(v);if(state.tab==='account')return accountPage(v)}}catch(e){v.innerHTML=`<div class="error-state"><h2>تعذر تحميل الصفحة</h2><p>${esc(e.message)}</p><button class="btn btn-soft" onclick="renderInternalView()">إعادة المحاولة</button></div>`}}
function pageHeader(kicker,title,sub,action=''){return`<header class="page-header"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${sub}</p></div>${action}</header>`}function kpi(label,value,icon,theme=''){return`<div class="kpi ${theme}"><span class="kpi-icon">${icon}</span><div><small>${label}</small><strong>${value??0}</strong></div></div>`}
async function adminHome(v){const [m,d]=await Promise.all([api('/api/dashboard/metrics'),api('/api/dashboard')]),k=m.kpis;v.innerHTML=pageHeader('مركز العمليات','نظرة عامة','كل ما يحتاج متابعة في مكان واحد',`<button class="btn btn-primary" onclick="newProject()">+ مشروع جديد</button>`)+`<section class="kpi-grid">${kpi('المشاريع النشطة',k.active_projects,'◒','purple')}${kpi('بانتظار العميل',k.waiting_client,'◷','gold')}${kpi('طلبات التعديل',k.revision_projects,'✎','red')}${kpi('المشاريع المعتمدة',k.approved_projects,'✓','green')}${kpi('التصميمات المعتمدة',k.approved_versions,'◇','blue')}</section><section class="attention-panel"><div class="section-heading"><div><span class="eyebrow">مركز المتابعة</span><h2>يحتاج متابعة</h2></div><span class="muted">الأولوية حسب حالة المشروع</span></div><div class="attention-list">${m.attention.length?m.attention.map(attentionItem).join(''):'<div class="empty-state">لا توجد عناصر تحتاج متابعة حالياً</div>'}</div></section><div class="dashboard-columns"><section class="panel"><div class="section-heading"><h2>أحدث المشاريع</h2><button class="link-button" onclick="state.tab='projects';renderInternal()">عرض الكل</button></div>${projectRows(d.projects)}</section><section class="panel"><div class="section-heading"><h2>آخر النشاطات</h2></div>${activityRows(d.activity)}</section></div>`}function attentionItem(p){const overdue=p.due_date&&new Date(p.due_date)<new Date(),health=overdue?'danger':p.status==='REVISION_REQUESTED'?'warning':'normal',text=p.status==='REVISION_REQUESTED'?`العميل طلب تعديل${p.latest_version?' على V'+p.latest_version:''}`:p.status==='WAITING_FOR_CLIENT'?'التصميم بانتظار اعتماد العميل':p.status==='IN_DESIGN'?'قيد العمل لدى المصمم':'المشروع يحتاج متابعة';return`<button class="attention-item ${health}" onclick="openProject(${p.id})"><span class="attention-symbol">${overdue?'!':p.status==='REVISION_REQUESTED'?'✎':'◷'}</span><span><b>${esc(p.name)}</b><small>${text} · ${ago(p.updated_at)}</small></span><span class="attention-arrow">←</span></button>`}function projectRows(rows){return rows.length?`<div class="project-list">${rows.map(p=>`<button class="project-row" onclick="openProject(${p.id})"><span class="project-avatar">${esc((p.name||'م').slice(0,1))}</span><span class="project-row-main"><b>${esc(p.name)}</b><small>${esc(p.client_name)} ${p.designer_name?'· '+esc(p.designer_name):''}</small></span><span>${badge(p.status)}</span><small class="project-time">${ago(p.updated_at)}</small><span>←</span></button>`).join('')}</div>`:'<div class="empty-state">لا توجد مشاريع بعد</div>'}function activityRows(rows){return rows.length?`<div class="activity-list">${rows.map(a=>`<div class="activity-row"><i></i><span><b>${esc(a.action)}</b><small>${esc(a.project_name)} · ${ago(a.created_at)}</small></span></div>`).join('')}</div>`:'<div class="empty-state">لا يوجد نشاط بعد</div>'}
async function designerHome(v){const d=await api('/api/dashboard/designer'),s=d.stats,firstName=(state.user.name||'').split(' ')[0]||'المصمم';const needs=d.projects.filter(p=>['NEW_TASK','REVISION_REQUESTED','IN_DESIGN','WAITING_FOR_DESIGNER'].includes(p.status));const waiting=d.projects.filter(p=>p.status==='WAITING_FOR_CLIENT');const approved=d.projects.filter(p=>['APPROVED','COMPLETED'].includes(p.status));v.innerHTML=`<div class="dashboard-greeting"><span class="eyebrow">نظرة عامة</span><h1>صباح الخير، ${esc(firstName)} 👋</h1><p class="muted">إليك ملخص أعمالك وما يحتاج إلى إجراء الآن.</p></div><section class="kpi-grid designer-kpis">${kpi('المشاريع النشطة',s.active||0,'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>','purple')}${kpi('تحتاج إجراء الآن',needs.length,'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>','gold')}${kpi('طلبات التعديل',s.revisions||0,'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg>','red')}${kpi('المعتمدة',s.approved||s.approved_versions||0,'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 15l-2 5 2-1 2 1-2-5"/><circle cx="12" cy="8" r="6"/><path d="m9 8 2 2 4-4"/></svg>','green')}</section><section class="panel action-section"><div class="section-heading"><div><h2>يحتاج إجراء الآن ⚡</h2><p>المشاريع التي تحتاج تدخلك المباشر</p></div><button class="link-button" onclick="state.designsFilter='needs_action';state.tab='projects';renderInternal()">عرض الكل</button></div>${designerActionCards(needs)}</section>${approved.length?`<section class="panel approved-preview-section"><div class="section-heading"><div><h2>أحدث التصاميم المعتمدة 🏆</h2><p>التصاميم التي تم الانتهاء منها واعتمادها</p></div><button class="link-button" onclick="state.tab='approved';renderInternal()">عرض الكل</button></div>${designerApprovedCards(approved.slice(0,4))}</section>`:''}`}
function designerActionCards(rows){if(!rows.length)return'<div class="empty-state-compact"><div class="empty-icon-pill">✨</div><h4>لا توجد مهام عاجلة حالياً</h4><p>أنت متابع كل مشاريعك بشكل ممتاز.</p></div>';return`<div class="dashboard-cards-grid">${rows.slice(0,4).map(p=>{const actionBtn=p.status==='REVISION_REQUESTED'?`<button class="btn btn-gold btn-block" onclick="openProject(${p.id})">فتح المهمة</button>`:p.status==='NEW_TASK'?`<button class="btn btn-primary btn-block" onclick="openProject(${p.id})">بدء التنفيذ</button>`:`<button class="btn btn-soft btn-block" onclick="openProject(${p.id})">فتح المشروع</button>`;const note=p.latest_revision_note||p.last_message;return`<article class="action-card"><div class="action-card-top"><div class="action-thumb">${projectThumbnail(p)}</div><div class="action-info"><span class="project-code">DES-${String(p.id).padStart(5,'0')}</span><h3 class="action-title">${esc(p.name)}</h3><div class="action-client-meta"><span class="client-name">${esc(p.client_name)}</span><span class="version-tag">${p.latest_version?'V'+p.latest_version:'V1'}</span></div>${projectStatusBadge(p.status)}</div></div>${note?`<div class="revision-snippet">"${esc(note.slice(0,60))}${note.length>60?'...':''}"</div>`:''}<div class="action-card-footer"><span class="card-time">${ago(p.updated_at)}</span><div class="action-btn-wrap">${actionBtn}</div></div></article>`}).join('')}</div>`}
function designerApprovedCards(rows){if(!rows.length)return'<div class="empty-state">لا توجد تصاميم معتمدة بعد</div>';return`<div class="approved-preview-row">${rows.map(p=>`<article class="approved-mini-card" onclick="openProject(${p.id})"><div class="approved-mini-thumb">${projectThumbnail(p)}<span class="verified-pill">✓</span></div><div class="approved-mini-body"><h4>${esc(p.name)}</h4><span class="muted">${esc(p.client_name)} · V${p.latest_version||1}</span></div></article>`).join('')}</div>`}
async function designerQueue(v){state.designsFilter=state.designsFilter||'all';state.designsSearch=state.designsSearch||'';state.designsPage=state.designsPage||1;const rows=await api('/api/projects');state.allDesignerProjects=rows;v.innerHTML=`<header class="page-header"><div><span class="eyebrow">مساحة المصمم</span><h1>تصاميمي</h1><p>جميع المشاريع المسندة إليك للتصميم.</p></div></header><div class="designs-toolbar"><div class="search-wrap"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" x2="16.65" y1="21" y2="16.65"/></svg><input class="search-input" id="designs-search" placeholder="ابحث باسم المشروع أو العميل..." value="${esc(state.designsSearch)}" oninput="state.designsSearch=this.value;state.designsPage=1;renderDesignsCardsOnly()"></div></div><div class="designs-tabs" id="designs-tabs-bar"></div><section class="designs-list-wrap" id="designs-cards-container"></section><div class="pagination-wrap" id="designs-pagination"></div>`;renderDesignsCardsOnly()}
function renderDesignsCardsOnly(){const rows=state.allDesignerProjects||[];const counts={all:rows.length,needs_action:rows.filter(p=>['NEW_TASK','REVISION_REQUESTED','WAITING_FOR_DESIGNER'].includes(p.status)).length,in_design:rows.filter(p=>p.status==='IN_DESIGN').length,waiting_client:rows.filter(p=>p.status==='WAITING_FOR_CLIENT').length,revisions:rows.filter(p=>p.status==='REVISION_REQUESTED').length,approved:rows.filter(p=>['APPROVED','COMPLETED'].includes(p.status)).length};const tabsBar=$('#designs-tabs-bar');if(tabsBar){tabsBar.innerHTML=`<button class="filter-tab ${state.designsFilter==='all'?'active':''}" onclick="setDesignsFilter('all')"><span>الكل</span><span class="tab-count">${counts.all}</span></button><button class="filter-tab ${state.designsFilter==='needs_action'?'active':''}" onclick="setDesignsFilter('needs_action')"><span>تحتاج إجراء</span><span class="tab-count count-gold">${counts.needs_action}</span></button><button class="filter-tab ${state.designsFilter==='in_design'?'active':''}" onclick="setDesignsFilter('in_design')"><span>قيد التنفيذ</span><span class="tab-count">${counts.in_design}</span></button><button class="filter-tab ${state.designsFilter==='waiting_client'?'active':''}" onclick="setDesignsFilter('waiting_client')"><span>بانتظار العميل</span><span class="tab-count">${counts.waiting_client}</span></button><button class="filter-tab ${state.designsFilter==='revisions'?'active':''}" onclick="setDesignsFilter('revisions')"><span>طلبات تعديل</span><span class="tab-count count-red">${counts.revisions}</span></button><button class="filter-tab ${state.designsFilter==='approved'?'active':''}" onclick="setDesignsFilter('approved')"><span>المعتمدة</span><span class="tab-count count-green">${counts.approved}</span></button>`}let filtered=rows.filter(p=>{if(state.designsFilter==='needs_action')return['NEW_TASK','REVISION_REQUESTED','WAITING_FOR_DESIGNER'].includes(p.status);if(state.designsFilter==='in_design')return p.status==='IN_DESIGN';if(state.designsFilter==='waiting_client')return p.status==='WAITING_FOR_CLIENT';if(state.designsFilter==='revisions')return p.status==='REVISION_REQUESTED';if(state.designsFilter==='approved')return['APPROVED','COMPLETED'].includes(p.status);return true});if(state.designsSearch){const q=state.designsSearch.trim().toLowerCase();filtered=filtered.filter(p=>(p.name||'').toLowerCase().includes(q)||(p.client_name||'').toLowerCase().includes(q)||String(p.id).includes(q))}const perPage=6,pages=Math.max(1,Math.ceil(filtered.length/perPage));state.designsPage=Math.min(state.designsPage||1,pages);const paged=filtered.slice((state.designsPage-1)*perPage,state.designsPage*perPage);const container=$('#designs-cards-container');if(container){if(!paged.length){container.innerHTML='<div class="empty-state"><h3>لا توجد مشاريع مطابقة</h3><p>جرّب تغيير التبويب أو تعديل نص البحث.</p></div>'}else{container.innerHTML=paged.map(p=>`<article class="project-list-card"><div class="project-list-thumb">${projectThumbnail(p)}</div><div class="project-list-main"><div class="project-list-meta"><span class="project-code">DES-${String(p.id).padStart(5,'0')}</span><h3 class="project-list-title">${esc(p.name)}</h3><div class="project-list-parties"><span class="client-label">العميل:</span><b>${esc(p.client_name)}</b><span class="designer-label">المصمم:</span><span>${esc(p.designer_name||state.user.name)}</span></div></div><div class="project-list-status-col"><span class="version-tag">${p.latest_version?'V'+p.latest_version:'V1'}</span>${projectStatusBadge(p.status)}<span class="project-list-time">آخر نشاط: ${ago(p.updated_at)}</span></div><div class="project-list-action-col"><button class="btn btn-primary" onclick="openProject(${p.id})">فتح المشروع</button><details class="action-menu"><summary aria-label="خيارات إضافية">⋮</summary><div><button onclick="openProject(${p.id})">فتح مساحة العمل</button><button onclick="navigator.clipboard.writeText('DES-${String(p.id).padStart(5,'0')}');toast('تم نسخ رمز المشروع')">نسخ رمز المشروع</button></div></details></div></div></article>`).join('')}}const pagWrap=$('#designs-pagination');if(pagWrap){if(pages<=1){pagWrap.innerHTML=''}else{let btns=`<button class="pag-btn" ${state.designsPage<=1?'disabled':''} onclick="setDesignsPage(${state.designsPage-1})">›</button>`;for(let i=1;i<=pages;i++){btns+=`<button class="pag-btn ${i===state.designsPage?'active':''}" onclick="setDesignsPage(${i})">${i}</button>`}btns+=`<button class="pag-btn" ${state.designsPage>=pages?'disabled':''} onclick="setDesignsPage(${state.designsPage+1})">‹</button>`;pagWrap.innerHTML=btns}}}
function setDesignsFilter(filter){state.designsFilter=filter;state.designsPage=1;renderDesignsCardsOnly()}
function setDesignsPage(page){state.designsPage=page;renderDesignsCardsOnly()}
async function approvedGallery(v){const rows=await api('/api/projects?status=APPROVED');const details=await Promise.all(rows.map(async p=>{try{return await api('/api/projects/'+p.id)}catch{return{project:p,versions:[],files:[]}}}));v.innerHTML=`<header class="page-header"><div><span class="eyebrow">أرشيف الأعمال</span><h1>المعتمدة</h1><p>التصاميم التي تم اعتمادها وإنهاء العمل عليها.</p></div></header><div class="approved-toolbar"><div class="search-wrap"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" x2="16.65" y1="21" y2="16.65"/></svg><input class="search-input" id="approved-search" placeholder="ابحث في التصاميم المعتمدة..." oninput="filterApprovedGallery(this.value)"></div><div class="approved-filters-wrap"><select class="select-filter" id="approved-client-filter" onchange="filterApprovedByClient(this.value)"><option value="">كل العملاء</option>${[...new Set(details.map(d=>d.client?.name).filter(Boolean))].map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></div></div><section class="approved-gallery-grid" id="approved-grid">${renderApprovedCards(details)}</section>`}
function renderApprovedCards(items){if(!items.length)return'<div class="empty-state-compact approved-empty-card"><div class="empty-icon-pill">🏆</div><h4>لا توجد تصاميم معتمدة حتى الآن</h4><p>ستظهر هنا التصاميم بعد اعتماد العميل لها.</p></div>';return items.map(d=>{const ver=d.versions[0],file=ver&&d.files.find(f=>f.version_id===ver.id&&f.mime?.startsWith('image/'));const imgUrl=file?`/api/files/${file.id}`:'';return`<article class="approved-gallery-card" data-name="${esc(d.project.name.toLowerCase())}" data-client="${esc((d.client?.name||'').toLowerCase())}" onclick="openProject(${d.project.id})"><div class="approved-gallery-media">${imgUrl?`<img src="${imgUrl}" alt="${esc(d.project.name)}">`:projectThumbnail(d.project)}<span class="approved-badge-tag"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>معتمد</span></div><div class="approved-gallery-info"><h3>${esc(d.project.name)}</h3><div class="approved-gallery-meta"><b>${esc(d.client?.name||'')}</b><span class="version-tag">${ver?'V'+ver.number:'—'}</span></div><small class="approved-date">${ver?.approved_at?fmt(ver.approved_at):ago(d.project.updated_at)}</small></div></article>`}).join('')}
function filterApprovedGallery(val){const q=val.toLowerCase().trim();document.querySelectorAll('.approved-gallery-card').forEach(c=>{const match=(c.dataset.name||'').includes(q)||(c.dataset.client||'').includes(q);c.hidden=!match})}
function filterApprovedByClient(client){const c=client.toLowerCase().trim();document.querySelectorAll('.approved-gallery-card').forEach(el=>{const match=!c||(el.dataset.client||'').includes(c);el.hidden=!match})}
async function notificationsPage(v){state.notifFilter=state.notifFilter||'all';const rows=await api('/api/notifications');state.cachedNotifications=rows;v.innerHTML=`<header class="page-header"><div><span class="eyebrow">التنبيهات</span><h1>الإشعارات</h1><p>آخر ما حدث في مشاريعك وتحديثات العملاء.</p></div><button class="btn btn-soft" onclick="markAllNotifsRead()">تحديد الكل كمقروء</button></header><div class="notif-tabs"><button class="filter-tab ${state.notifFilter==='all'?'active':''}" onclick="setNotifFilter('all')">الكل</button><button class="filter-tab ${state.notifFilter==='unread'?'active':''}" onclick="setNotifFilter('unread')">غير المقروء</button><button class="filter-tab ${state.notifFilter==='revisions'?'active':''}" onclick="setNotifFilter('revisions')">طلبات التعديل</button><button class="filter-tab ${state.notifFilter==='projects'?'active':''}" onclick="setNotifFilter('projects')">المشاريع</button><button class="filter-tab ${state.notifFilter==='messages'?'active':''}" onclick="setNotifFilter('messages')">المحادثات</button></div><section class="notif-feed-wrap" id="notif-feed"></section>`;renderNotifFeed()}
function setNotifFilter(f){state.notifFilter=f;document.querySelectorAll(".notif-tabs .filter-tab").forEach(b=>b.classList.remove("active"));event?.target?.closest("button")?.classList.add("active");renderNotifFeed()}
function renderNotifFeed(){const rows=state.cachedNotifications||[];let list=rows;if(state.notifFilter==='unread')list=rows.filter(n=>!n.read_at);if(state.notifFilter==='revisions')list=rows.filter(n=>n.title.includes('تعديل')||n.body.includes('تعديل'));if(state.notifFilter==='projects')list=rows.filter(n=>n.title.includes('مشروع')||n.title.includes('مهمة')||n.title.includes('تصميم')||n.body.includes('مشروع'));if(state.notifFilter==='messages')list=rows.filter(n=>n.title.includes('رسالة')||n.body.includes('رسالة'));const feed=$('#notif-feed');if(!feed)return;if(!list.length){feed.innerHTML='<div class="empty-state-compact"><div class="empty-icon-pill">🔔</div><h4>لا توجد إشعارات هنا</h4><p>ستظهر التحديثات فور حدوث أي نشاط جديد.</p></div>';return}const now=Date.now(),groups={today:[],yesterday:[],older:[]};list.forEach(n=>{const age=now-new Date(n.created_at).getTime();if(age<86400000)groups.today.push(n);else if(age<172800000)groups.yesterday.push(n);else groups.older.push(n)});let html='';if(groups.today.length)html+=`<div class="notif-group"><h3 class="notif-group-title">اليوم</h3>${groups.today.map(notifItemHtml).join('')}</div>`;if(groups.yesterday.length)html+=`<div class="notif-group"><h3 class="notif-group-title">أمس</h3>${groups.yesterday.map(notifItemHtml).join('')}</div>`;if(groups.older.length)html+=`<div class="notif-group"><h3 class="notif-group-title">أقدم</h3>${groups.older.map(notifItemHtml).join('')}</div>`;feed.innerHTML=html}
function notifItemHtml(n){const isRev=n.title.includes('تعديل')||n.body.includes('تعديل');const isApp=n.title.includes('اعتماد')||n.body.includes('اعتماد');const isMsg=n.title.includes('رسالة');const iconClass=isRev?'notif-icon-red':isApp?'notif-icon-green':isMsg?'notif-icon-dark':'notif-icon-purple';const iconSvg=isRev?'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg>':isApp?'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>':isMsg?'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>':'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect width="20" height="14" x="2" y="7" rx="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg>';return`<div class="notif-item ${n.read_at?'':'unread'}" onclick="${n.project_id?`openProject(${n.project_id})`:''}"><div class="notif-icon ${iconClass}">${iconSvg}</div><div class="notif-content"><div class="notif-content-top"><b>${esc(n.title)}</b><time>${ago(n.created_at)}</time></div><p>${esc(n.body)}</p>${n.project_id?`<span class="notif-project-tag">مشروع #${n.project_id}</span>`:''}</div>${!n.read_at?'<span class="unread-dot" title="غير مقروء"></span>':''}</div>`}
async function markAllNotifsRead(){try{await api('/api/notifications/read',{method:'POST',body:'{}'});state.unreadCount=0;if(state.cachedNotifications)state.cachedNotifications.forEach(n=>n.read_at=new Date().toISOString());renderNotifFeed();$('#nav-notif-count')?.remove();$('.top-notif-dot')?.remove();toast('تم تحديد جميع الإشعارات كمقروءة')}catch(e){toast(e.message,'error')}}
function accountPage(v){const u=state.user;const initial=esc((u.name||'G').slice(0,1));v.innerHTML=`<header class="page-header"><div><span class="eyebrow">حساب المصمم</span><h1>إعدادات الحساب</h1><p>بياناتك الشخصية وتفضيلات الدخول والأمان.</p></div></header><div class="account-settings-container"><div class="account-profile-summary"><div class="account-avatar-large">${initial}</div><div class="account-profile-meta"><h2>${esc(u.name)}</h2><span class="role-badge">مصمم</span><span class="account-email-sub">${esc(u.email||u.phone||'—')}</span></div></div><form class="account-card-modern" id="account-form"><div class="settings-section"><div class="settings-section-header"><h3>معلومات الحساب</h3><p class="muted">البيانات الأساسية المسجلة في ملفك الشخصي</p></div><div class="settings-grid"><div class="field"><label>الاسم الكامل</label><input name="name" value="${esc(u.name||'')}" required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" value="${esc(u.email||'')}"></div><div class="field"><label>رقم الجوال</label><input name="phone" value="${esc(u.phone||'')}"></div></div></div><div class="settings-section"><div class="settings-section-header"><h3>الأمان</h3><p class="muted">يمكنك تحديث كلمة المرور الخاصة بك في أي وقت.</p></div><div class="field"><label>كلمة المرور الجديدة</label><input name="password" type="password" placeholder="اتركها فارغة إذا لم ترد تغييرها" autocomplete="new-password"></div></div><div class="settings-actions"><button class="btn btn-gold btn-block account-submit-btn">حفظ التغييرات</button></div></form></div>`;$('#account-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{const d=await api('/api/account',{method:'PATCH',body:JSON.stringify(b)});state.user=d.user;toast('تم حفظ التغييرات بنجاح');renderInternal()}catch(x){toast(x.message,'error')}}}
async function internalProjects(v,status=''){const rows=await api('/api/projects'+(status?'?status='+status:''));v.innerHTML=pageHeader(state.user.role==='ADMIN'?'إدارة المشاريع':'مساحة المصمم',state.user.role==='ADMIN'?'المشاريع':'مشاريعي','تابع حالة كل مشروع وآخر نشاط',state.user.role==='ADMIN'?'<button class="btn btn-primary" onclick="newProject()">+ مشروع جديد</button>':'')+`<div class="filter-bar"><input class="search-input" placeholder="ابحث باسم المشروع أو العميل" oninput="filterProjectRows(this.value)"><div class="filter-chips"><button class="filter-chip active" onclick="filterStatus('')">الكل</button><button class="filter-chip" onclick="filterStatus('IN_DESIGN')">قيد التصميم</button><button class="filter-chip" onclick="filterStatus('WAITING_FOR_CLIENT')">بانتظار العميل</button><button class="filter-chip" onclick="filterStatus('REVISION_REQUESTED')">طلبات التعديل</button><button class="filter-chip" onclick="filterStatus('APPROVED')">المعتمدة</button></div></div><section class="panel projects-panel"><div class="table-head"><span>المشروع</span><span>العميل</span><span>المصمم</span><span>الحالة</span><span>آخر نشاط</span><span></span></div><div id="project-results">${rows.length?rows.map(p=>`<button class="table-row" data-search="${esc((p.name+' '+p.client_name).toLowerCase())}" onclick="openProject(${p.id})"><span class="table-project"><i class="project-avatar">${esc((p.name||'م').slice(0,1))}</i><b>${esc(p.name)}</b></span><span>${esc(p.client_name)}</span><span>${esc(p.designer_name||'غير مسند')}</span><span>${badge(p.status)}</span><span>${ago(p.updated_at)}</span><span>←</span></button>`).join(''):'<div class="empty-state">لا توجد مشاريع</div>'}</div></section>`}
function filterProjectRows(value){const q=value.toLowerCase();document.querySelectorAll('.table-row').forEach(r=>r.hidden=!r.dataset.search.includes(q))}
function filterStatus(status){state.tab=status?status==='WAITING_FOR_CLIENT'?'waiting':status==='APPROVED'?'approved':'projects':'projects';renderInternal()}
async function clients(v){const rows=await api('/api/clients');v.innerHTML=pageHeader('إدارة العملاء','العملاء','بيانات العملاء وإدارة صلاحيات الوصول','<button class="btn btn-primary" onclick="newClient()">+ عميل جديد</button>')+`<section class="panel clients-panel"><div class="table-head"><span>العميل</span><span>البريد</span><span>الهاتف</span><span>الحالة</span><span>إجراءات</span></div>${rows.map(c=>`<div class="table-row client-row"><span class="table-project"><i class="project-avatar">${esc((c.name||'ع').slice(0,1))}</i><b>${esc(c.name)}</b></span><span>${esc(c.email||'—')}</span><span>${esc(c.phone||'—')}</span><span>${c.active?'<span class="status status-approved"><i></i>نشط</span>':'<span class="status status-cancelled"><i></i>معطل</span>'}</span><span class="row-actions"><button class="link-button" onclick="editClient(${c.id},'${esc(c.name)}','${esc(c.email||'')}','${esc(c.phone||'')}')">تعديل</button><button class="link-button danger-text" onclick="toggleClient(${c.id},${c.active})">${c.active?'تعطيل':'تفعيل'}</button></span></div>`).join('')||'<div class="empty-state">لا يوجد عملاء بعد</div>'}</section>`}async function designers(v){const rows=await api('/api/designers');v.innerHTML=pageHeader('إدارة الفريق','المصممون','فريق التصميم الداخلي','<button class="btn btn-primary" onclick="newDesigner()">+ مصمم جديد</button>')+`<section class="panel clients-panel"><div class="table-head"><span>المصمم</span><span>البريد</span><span>الجوال</span><span>الحالة</span></div>${rows.map(c=>`<div class="table-row"><span class="table-project"><i class="project-avatar">${esc((c.name||'م').slice(0,1))}</i><b>${esc(c.name)}</b></span><span>${esc(c.email||'—')}</span><span>${esc(c.phone||'—')}</span><span>${c.active?'<span class="status status-approved"><i></i>نشط</span>':'<span class="status status-cancelled"><i></i>معطل</span>'}</span></div>`).join('')||'<div class="empty-state">لا يوجد مصممون بعد</div>'}</section>`}async function adminActivity(v){const d=await api('/api/dashboard');v.innerHTML=pageHeader('المراقبة','النشاط','سجل آخر التحديثات في المشاريع')+`<section class="panel activity-panel">${activityRows(d.activity)}</section>`}
function modal(title,body,submit,button='حفظ'){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><form class="modal"><button type="button" class="modal-close" aria-label="إغلاق">×</button><span class="eyebrow">G.PACK</span><h2>${title}</h2>${body}<div class="modal-actions"><button type="button" class="btn btn-soft modal-cancel">إلغاء</button><button class="btn btn-primary">${button}</button></div></form></div>`);const m=$('#modal');m.querySelectorAll('.modal-close,.modal-cancel').forEach(x=>x.onclick=()=>m.remove());m.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=m.querySelector('button[type=submit]');try{await submit(new FormData(e.target));m.remove();toast('تم الحفظ');renderInternal()}catch(x){toast(x.message,'error')}finally{if(b)b.disabled=false}}}
function newClient(){modal('إضافة عميل','<div class="field"><label>اسم العميل</label><input name="name" required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email"></div><div class="field"><label>رقم الجوال</label><input name="phone"></div>',f=>api('/api/clients',{method:'POST',body:JSON.stringify(Object.fromEntries(f))}))}function editClient(id,name,email,phone){modal('تعديل بيانات العميل',`<div class="field"><label>اسم العميل</label><input name="name" value="${name}" required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" value="${email}"></div><div class="field"><label>رقم الجوال</label><input name="phone" value="${phone}"></div>`,f=>api('/api/clients/'+id,{method:'PATCH',body:JSON.stringify(Object.fromEntries(f))}))}async function toggleClient(id,active){if(!confirm(active?'هل تريد تعطيل العميل؟':'هل تريد تفعيل العميل؟'))return;try{await api('/api/clients/'+id,{method:'PATCH',body:JSON.stringify({active:!active})});renderInternal()}catch(e){toast(e.message,'error')}}function newDesigner(){modal('إضافة مصمم','<div class="field"><label>الاسم</label><input name="name" required></div><div class="field"><label>البريد الإلكتروني (اختياري)</label><input name="email" type="email"></div><div class="field"><label>رقم الجوال (اختياري)</label><input name="phone" placeholder="0551234567"></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" minlength="8" required></div>',f=>api('/api/designers',{method:'POST',body:JSON.stringify(Object.fromEntries(f))}))}async function newProject(){const [cs,ds]=await Promise.all([api('/api/clients'),api('/api/designers')]);modal('إنشاء مشروع','<div class="field"><label>اسم المشروع</label><input name="name" required></div><div class="field"><label>العميل</label><select name="client_id" required>'+cs.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')+'</select></div><div class="field"><label>المصمم</label><select name="designer_id"><option value="">— لاحقاً —</option>'+ds.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')+'</select></div><div class="field"><label>الوصف</label><textarea name="description" rows="2"></textarea></div><div class="field"><label>الموجز</label><textarea name="brief" rows="4"></textarea></div>',f=>api('/api/projects',{method:'POST',body:JSON.stringify(Object.fromEntries(f))}))}
function normalizeOptions(options=[],files=[]){const unassigned=files.filter(f=>!f.option_id&&f.mime?.startsWith('image/'));return options.map((o,i)=>({...o,files:files.filter(f=>String(f.option_id)===String(o.id)&&f.mime?.startsWith('image/')).length?files.filter(f=>String(f.option_id)===String(o.id)&&f.mime?.startsWith('image/')):(unassigned[i]?[unassigned[i]]:[])}))}function optionImage(o,portal=false){const f=o.files?.[0];return f?`<img src="${portal?'/api/portal/'+state.portalData.project.id+'/files/'+f.id:'/api/files/'+f.id}" alt="${esc(o.name)}">`:'<span>لا توجد معاينة</span>'}
function fmtFileSize(bytes) {
  if (!bytes || bytes <= 0) return '0 KB';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.ceil(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function getFileTypeInfo(f) {
  const name = f.original_name || '';
  const ext = (name.split('.').pop() || '').toUpperCase();
  const mime = (f.mime || '').toLowerCase();
  if (mime.startsWith('image/')) return { type: ext || 'PNG', isImage: true };
  if (ext === 'PDF' || mime.includes('pdf')) return { type: 'PDF', badgeClass: 'file-type-pdf' };
  if (['AI', 'EPS'].includes(ext)) return { type: 'AI', badgeClass: 'file-type-ai' };
  if (ext === 'PSD') return { type: 'PSD', badgeClass: 'file-type-psd' };
  if (['ZIP', 'RAR', '7Z', 'TAR', 'GZ'].includes(ext)) return { type: 'ZIP', badgeClass: 'file-type-zip' };
  if (['DOC', 'DOCX'].includes(ext)) return { type: 'DOC', badgeClass: 'file-type-doc' };
  if (['XLS', 'XLSX', 'CSV'].includes(ext)) return { type: 'XLS', badgeClass: 'file-type-xls' };
  return { type: ext || 'FILE', badgeClass: 'file-type-default' };
}

function renderWorkspaceFileRow(f) {
  const info = getFileTypeInfo(f);
  const iconHtml = info.isImage
    ? `<div class="file-thumb-mini-wrap"><img src="/api/files/${f.id}" alt="${esc(f.original_name)}" class="file-thumb-mini" loading="lazy"></div>`
    : `<div class="file-icon-badge ${info.badgeClass}"><span>${info.type}</span></div>`;
  return `<div class="compact-file-row"><div class="file-row-main">${iconHtml}<div class="file-row-details"><span class="file-row-name" title="${esc(f.original_name)}">${esc(f.original_name)}</span><span class="file-row-sub">${info.type} • ${fmtFileSize(f.size)}</span></div></div><div class="file-row-actions"><a href="/api/files/${f.id}" target="_blank" class="file-action-link" title="فتح الملف">فتح</a><a href="/api/files/${f.id}" download="${esc(f.original_name)}" class="file-download-btn" title="تنزيل">⤓</a></div></div>`;
}

function renderWorkspaceFilesList(files, activeTab) {
  const filtered = (files || []).filter(f => {
    if (activeTab === 'client') return f.uploaded_by_type === 'CLIENT';
    return f.uploaded_by_type === 'DESIGNER' || f.uploaded_by_type === 'ADMIN';
  });
  if (!filtered.length) {
    const emptyMsg = activeTab === 'client' ? 'لا توجد ملفات من العميل بعد' : 'لا توجد ملفات من المصمم بعد';
    return `<div class="tiny-files-empty"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg><span>${emptyMsg}</span></div>`;
  }
  return filtered.map(renderWorkspaceFileRow).join('');
}

function setWorkspaceFilesTab(tab) {
  state.workspaceFilesTab = tab;
  document.querySelectorAll('.files-tab-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.tab === tab);
  });
  const listEl = document.querySelector('#workspace-files-list');
  if (listEl && state.project?.files) {
    listEl.innerHTML = renderWorkspaceFilesList(state.project.files, tab);
  }
}

function renderWorkspaceFilesPanel(files = []) {
  state.workspaceFilesTab = state.workspaceFilesTab || 'designer';
  const designerCount = files.filter(f => f.uploaded_by_type === 'DESIGNER' || f.uploaded_by_type === 'ADMIN').length;
  const clientCount = files.filter(f => f.uploaded_by_type === 'CLIENT').length;
  return `<div class="compact-files-panel"><div class="files-panel-top"><h3 class="files-panel-title">الملفات</h3><div class="files-tabs-wrap"><button type="button" class="files-tab-btn ${state.workspaceFilesTab === 'designer' ? 'active' : ''}" data-tab="designer" onclick="setWorkspaceFilesTab('designer')"><span>ملفات المصمم</span><span class="files-count-badge">${designerCount}</span></button><button type="button" class="files-tab-btn ${state.workspaceFilesTab === 'client' ? 'active' : ''}" data-tab="client" onclick="setWorkspaceFilesTab('client')"><span>ملفات العميل</span><span class="files-count-badge">${clientCount}</span></button></div></div><div class="compact-files-list" id="workspace-files-list">${renderWorkspaceFilesList(files, state.workspaceFilesTab)}</div></div>`;
}

async function openProject(id){closeStream();const d=await api('/api/projects/'+id),p=d.project;state.project=d;const revisions=d.revisions||[],latestOptions=d.versions[0]?normalizeOptions(d.versions[0].options||[],d.files.filter(f=>f.version_id===d.versions[0].id)):[];document.querySelector('#internal-view').innerHTML=`<div class="workspace-top"><button class="back-button" onclick="state.tab='projects';renderInternal()">→ رجوع للمشاريع</button><div class="workspace-title"><span class="eyebrow">مساحة المشروع</span><h1>${esc(p.name)}</h1><div>${badge(p.status)} <span class="muted">${esc(d.client.name)}</span></div></div><button class="btn btn-gold" onclick="generateAccess(${p.id},'${esc(d.client.phone||'')}','${esc(d.client.name||'')}')">رابط العميل</button></div><div class="workspace-grid"><aside class="workspace-side panel"><h3>الموجز</h3><p class="brief-text">${esc(p.brief||p.description||'لم تتم إضافة موجز بعد')}</p>${renderWorkspaceFilesPanel(d.files)}</aside><section class="panel workspace-chat"><div class="section-heading"><h2>المحادثة</h2><span class="live-pill"><i></i> مباشرة</span></div><div class="messages" id="messages"></div><form class="composer" id="internal-composer"><input type="file" id="internal-file" hidden accept="image/jpeg,image/png,image/webp,application/pdf,text/plain"><button type="button" class="attach-button" id="internal-attach" aria-label="إرفاق ملف">⌕</button><input name="body" placeholder="اكتب رسالة أو أرفق ملفاً..." autocomplete="off"><button class="send-button">➤</button><div id="internal-attachment" class="attachment-preview hidden"></div></form></section><aside class="workspace-review panel"><div class="section-heading"><h2>آخر نسخة</h2>${d.versions[0]?`<span class="version-pill">V${d.versions[0].number}</span>`:''}</div>${d.versions[0]?`<div class="internal-preview">${internalPreview(d)}</div><p class="version-note">${esc(d.versions[0].notes||'بدون ملاحظات')}</p>${latestOptions.length?'<div class="designer-options"><div class="option-list"><b>خيارات التصميم</b>'+latestOptions.map((o,i)=>`<div class="designer-option-card"><div class="option-preview">${optionImage(o)}</div><strong>الخيار ${i+1}</strong><small>${esc(o.name)}</small><span>${o.status==='SELECTED'?'مختار للمراجعة':o.status==='APPROVED'?'معتمد':'مقترح'}</span></div>`).join('')+'</div></div>':''}${state.user.role==='DESIGNER'?(p.status==='NEW_TASK'?'<button class="btn btn-gold btn-block" onclick="startProject('+p.id+')">بدء التنفيذ</button>':'<button class="btn btn-primary btn-block" onclick="uploadVersion('+p.id+')">تسليم التصميم</button>'):''}`:'<div class="empty-state"><h3>لم يتم تسليم تصميم رسمي بعد</h3><p>مرفقات المحادثة تبقى في الملفات فقط. استخدم زر تسليم التصميم لإرسال V1 للعميل.</p></div>'+ (state.user.role==='DESIGNER'?(p.status==='NEW_TASK'?'<button class="btn btn-gold btn-block" onclick="startProject('+p.id+')">بدء التنفيذ</button>':'<button class="btn btn-primary btn-block" onclick="uploadVersion('+p.id+')">تسليم التصميم V1</button>'):'')}<h3>طلبات التعديل</h3>${revisions.map(r=>`<div class="revision-card"><b>تعديل على V${r.version_number}${r.option_name?' — '+esc(r.option_name):''}</b><p>${esc(r.request)}</p><small>${fmt(r.created_at)}</small></div>`).join('')||'<div class="compact-empty">لا توجد طلبات تعديل</div>'}</aside></div>`;const ms=await api('/api/projects/'+id+'/messages');$('#messages').innerHTML='';ms.forEach(appendMessage);$('#internal-attach').onclick=()=>$('#internal-file').click();$('#internal-file').onchange=e=>{const f=e.target.files[0],box=$('#internal-attachment');if(!f){box.classList.add('hidden');return}box.classList.remove('hidden');box.innerHTML=`<span>▧</span><b>${esc(f.name)}</b><small>${Math.ceil(f.size/1024)} KB</small><button type="button">×</button>`;box.querySelector('button').onclick=()=>{e.target.value='';box.classList.add('hidden')}};$('#internal-composer').onsubmit=async e=>{e.preventDefault();const input=e.target.body,file=$('#internal-file').files[0];if(!input.value.trim()&&!file)return;try{if(file){const fd=new FormData();fd.append('file',file);await api('/api/projects/'+id+'/files',{method:'POST',body:fd})}if(input.value.trim())await api('/api/projects/'+id+'/messages',{method:'POST',body:JSON.stringify({body:input.value.trim(),client_event_id:crypto.randomUUID()})});e.target.reset();$('#internal-attachment').classList.add('hidden');toast('تم الإرسال')}catch(x){toast(x.message,'error')}};openStream('/api/projects/'+id+'/stream',x=>{if(x.type==='message')appendMessage(x.message);else if(['version','revision','approved','file','status'].includes(x.type))openProject(id)})}function fileItem(f){return`<div class="file-item"><span class="file-icon">${f.mime.startsWith('image/')?'▧':'▤'}</span><span><b>${esc(f.original_name)}</b><small>${f.uploaded_by_type==='CLIENT'?'ملف من العميل':'ملف من المصمم'} · ${Math.ceil(f.size/1024)} KB</small></span><a href="/api/files/${f.id}" target="_blank">فتح</a></div>`}function internalPreview(d){const f=d.files.find(x=>x.version_id===d.versions[0].id&&x.mime.startsWith('image/'));return f?`<a href="/api/files/${f.id}" target="_blank"><img src="/api/files/${f.id}" alt="V${d.versions[0].number}"></a>`:'<span class="muted">ملف التصميم متاح ضمن الملفات</span>'}async function loadMessages(){const ms=await api('/api/projects/'+state.project.project.id+'/messages');$('#messages').innerHTML='';ms.forEach(appendMessage)}function appendMessage(m){const el=document.createElement('div');el.className='message '+(m.sender_type===state.user?.role?'mine':'');el.innerHTML=`${esc(m.body)}<time>${esc(m.sender_name||'')} · ${fmt(m.created_at)}</time>`;$('#messages')?.append(el);if($('#messages'))$('#messages').scrollTop=$('#messages').scrollHeight}async function startProject(id){try{await api('/api/projects/'+id+'/start',{method:'POST',body:'{}'});toast('بدأت مهمة التصميم');openProject(id)}catch(e){toast(e.message,'error')}}function uploadVersion(id){modal('تسليم التصميم','<div class="field"><label>ملاحظات النسخة</label><textarea name="notes" rows="3"></textarea></div><div class="field"><label>أسماء الخيارات (اختياري)</label><input name="options" placeholder="الخيار A, الخيار B, الخيار C"></div><div class="field"><label>ملفات الخيار A</label><input name="option_0" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></div><div class="field"><label>ملفات الخيار B</label><input name="option_1" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></div><div class="field"><label>ملفات الخيار C</label><input name="option_2" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></div>',async f=>{const r=await fetch('/api/projects/'+id+'/versions',{method:'POST',body:f,credentials:'same-origin'});if(!r.ok)throw Error((await r.json()).error||'فشل رفع النسخة');return r.json()},'إرسال للمراجعة')}function normalizeSaudiPhone(value){let p=String(value||'').replace(/[^0-9+]/g,'');if(p.startsWith('00'))p='+'+p.slice(2);if(p.startsWith('+966'))p=p.slice(1);else if(p.startsWith('966'))p=p;else if(p.startsWith('05'))p='966'+p.slice(1);else if(p.startsWith('5'))p='966'+p;else return '';return /^9665[0-9]{8}$/.test(p)?p:''}async function generateAccess(id,phone='',clientName='العميل'){try{const d=await api('/api/projects/'+id+'/access',{method:'POST',body:'{}'}),url=new URL(d.url,location.origin).href,waPhone=normalizeSaudiPhone(phone),waText=encodeURIComponent(`مرحبًا،\n\nتم تجهيز بوابة خاصة لمتابعة مشروع التصميم الخاص بكم مع G.PACK.\n\nيمكنكم الدخول إلى المشروع ومتابعة التصميم والتواصل مع المصمم وطلب التعديلات واعتماد التصميم من خلال الرابط التالي:\n\n${url}\n\nمع تحيات فريق G.PACK`);modal('رابط بوابة العميل',`<p class="muted">شارك هذا الرابط مع ${esc(clientName)} للوصول إلى مشروعه.</p><div class="copy-link"><input id="portal-link" value="${esc(url)}" readonly><button type="button" onclick="copyPortalLink()">نسخ</button></div><div class="link-status"><span class="status status-approved"><i></i>الرابط نشط</span></div><div class="link-actions"><a class="btn btn-primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">فتح الرابط</a>${waPhone?`<a class="btn whatsapp-button" href="https://wa.me/${waPhone}?text=${waText}" target="_blank" rel="noopener noreferrer">إرسال عبر واتساب</a>`:'<button type="button" class="btn btn-soft" onclick="state.tab=\'clients\';renderInternal();toast(\'أضف رقم جوال العميل لاستخدام الإرسال عبر واتساب\')">إضافة رقم واتساب</button>'}</div><hr><button type="button" class="link-danger" onclick="regenerateAccess(${id},'${esc(phone)}','${esc(clientName)}')">تجديد الرابط</button><button type="button" class="link-danger" onclick="revokeAccess(${id})">إلغاء الوصول</button>`,async()=>{},'إغلاق')}catch(e){toast('تعذر إنشاء رابط العميل','error')}}async function copyPortalLink(){try{await navigator.clipboard.writeText($('#portal-link').value);toast('تم نسخ رابط العميل')}catch{toast('تعذر النسخ تلقائياً، حدّد الرابط وانسخه يدوياً','error')}}async function regenerateAccess(id,phone,name){if(!confirm('سيتم إلغاء الرابط الحالي وإنشاء رابط جديد. هل تريد المتابعة؟'))return;$('#modal')?.remove();generateAccess(id,phone,name)}async function revokeAccess(id){if(!confirm('لن يتمكن العميل من فتح البوابة بالرابط الحالي. هل تريد إلغاء الوصول؟'))return;try{await api('/api/projects/'+id+'/access/revoke',{method:'POST',body:'{}'});$('#modal')?.remove();toast('تم إلغاء وصول العميل');renderInternal()}catch(e){toast(e.message,'error')}}
async function renderPortal(){try{const m=await api('/api/portal/me'),full=await api('/api/portal/'+m.project.id);state.portalData=full;state.portalProject=m.project;clientPortalView()}catch(e){document.body.innerHTML=`<main class="login"><div class="login-card"><div class="brand brand-large"><img class="brand-image" src="/brand-logo.png" alt="G.PACK"></div><h2>تعذر الوصول إلى المشروع</h2><p class="muted">${esc(e.message)}<br>استخدم رابط الوصول المرسل من G.PACK.</p></div></main>`}}function clientPortalView(){closeStream();const d=state.portalData,p=d.project,v=d.versions[0],vfiles=v?d.files.filter(f=>f.version_id===v.id):[],clientOptions=v?normalizeOptions(v.options||[],vfiles):[],selectedOption=clientOptions.find(o=>o.status==='SELECTED'||o.status==='APPROVED'),mainFiles=selectedOption?selectedOption.files:clientOptions.length?[]:vfiles;document.body.innerHTML=`<main class="client-portal"><header class="client-header"><div class="brand"><img class="brand-image" src="/brand-logo.png" alt="G.PACK"></div><div class="client-identity"><span class="eyebrow">مساحة العميل</span><b>${esc(d.client.name)}</b></div></header><section class="client-hero"><div><span class="eyebrow">مشروعك</span><h1>${esc(p.name)}</h1><p>${esc(statusText[p.status]||'تابع آخر مستجدات مشروعك')}</p></div><div class="client-status">${badge(p.status)}<small>آخر تحديث ${ago(p.updated_at)}</small></div></section><section class="client-review"><div class="section-heading"><div><span class="eyebrow">المراجعة الحالية</span><h2>${v?'التصميم الأخير':'التصميم قيد التجهيز'}</h2></div>${v?`<span class="version-pill">V${v.number}</span>`:''}</div>${v?`<div class="client-design-stage">${clientPreview(mainFiles,v.number)}</div>${clientOptions.length?`<div class="client-options"><div class="section-heading"><h3>خيارات التصميم</h3>${clientOptions.length>1?'<button class="btn btn-soft" id="compare-options">مقارنة التصميمات</button>':''}</div><div class="option-grid">${clientOptions.map((o,i)=>`<div class="option-card"><div class="option-preview">${clientOptionPreview(d,o,vfiles)}</div><b>الخيار ${i+1} · ${esc(o.name)}</b><small>${o.status==='APPROVED'?'معتمد':o.status==='SELECTED'?'مختار للمراجعة':'مقترح'}</small><button type="button" class="btn btn-soft" onclick="selectOption(${o.id})">اختيار هذا التصميم</button></div>`).join('')}</div></div>`:''}<div class="client-review-footer"><div><b>${v.status==='APPROVED'?'تم اعتماد هذه النسخة':'بانتظار اعتمادك'}</b><p>${esc(v.notes||'راجع التصميم وأرسل ملاحظاتك أو اعتمده')}</p></div>${v.status==='PENDING'?'<div class="client-actions"><button class="btn btn-revision" id="client-revision">✎ طلب تعديل</button><button class="btn btn-approve" id="client-approve">✓ اعتماد التصميم</button></div>':''}</div>`:'<div class="design-empty"><span>✦</span><h3>التصميم قيد التجهيز</h3><p>سيظهر التصميم هنا بمجرد رفعه من المصمم.</p></div>'}${d.versions.length>1?`<div class="version-history"><span>النسخ السابقة</span>${d.versions.slice(1).map(x=>`<span class="version-chip">V${x.number} · ${x.status==='APPROVED'?'معتمدة':'سابقة'}</span>`).join('')}</div>`:''}</section><section class="client-conversation"><div class="section-heading"><div><span class="eyebrow">تواصل مباشر</span><h2>المحادثة</h2></div><span class="live-pill"><i></i> مباشرة</span></div><div class="messages" id="messages"></div><form class="client-composer" id="client-composer"><input type="file" id="client-file" hidden accept="image/jpeg,image/png,image/webp,application/pdf,text/plain"><button type="button" class="attach-button" id="attach-button" aria-label="إرفاق ملف">⌕</button><input name="body" placeholder="اكتب رسالتك أو ملاحظتك هنا..." autocomplete="off"><button class="send-button" aria-label="إرسال">➤</button><div id="attachment-preview" class="attachment-preview hidden"></div></form></section><section class="client-secondary"><details open><summary><span><b>الملفات</b><small>مرفقات المشروع</small></span><i>⌄</i></summary><div>${d.files.map(clientFile).join('')||'<div class="compact-empty">لم تتم إضافة ملفات بعد</div>'}</div></details><details><summary><span><b>تفاصيل المشروع</b><small>الموجز والملاحظات</small></span><i>⌄</i></summary><p class="client-brief">${esc(p.brief||p.description||'لم تتم إضافة تفاصيل بعد')}</p></details><details><summary><span><b>سجل المشروع</b><small>آخر التحديثات</small></span><i>⌄</i></summary><div class="client-timeline">${d.activity.slice(0,6).map(a=>`<div><i></i><span><b>${esc(a.action)}</b><small>${ago(a.created_at)}</small></span></div>`).join('')||'<div class="compact-empty">لا يوجد نشاط بعد</div>'}</div></details></section></main>`;loadPortalMessages();$('#attach-button').onclick=()=>$('#client-file').click();$('#client-file').onchange=e=>{const f=e.target.files[0],box=$('#attachment-preview');if(!f){box.classList.add('hidden');return}box.classList.remove('hidden');box.innerHTML=`<span>▧</span><b>${esc(f.name)}</b><small>${Math.ceil(f.size/1024)} KB</small><button type="button">×</button>`;box.querySelector('button').onclick=()=>{e.target.value='';box.classList.add('hidden')}};$('#client-composer').onsubmit=async e=>{e.preventDefault();const input=e.target.body,file=$('#client-file').files[0];if(!input.value.trim()&&!file)return;const btn=e.target.querySelector('.send-button');btn.disabled=true;try{if(file){const fd=new FormData();fd.append('file',file);await api('/api/portal/'+p.id+'/files',{method:'POST',body:fd})}if(input.value.trim())await api('/api/portal/'+p.id+'/messages',{method:'POST',body:JSON.stringify({body:input.value.trim(),client_event_id:crypto.randomUUID()})});e.target.reset();$('#attachment-preview').classList.add('hidden');toast('تم الإرسال')}catch(x){toast(x.message,'error')}finally{btn.disabled=false}};$('#compare-options')?.addEventListener('click',()=>compareOptions(v,d));if(v?.status==='PENDING'){$('#client-revision').onclick=()=>modal('طلب تعديل على V'+v.number,'<div class="field"><label>ما الذي يحتاج إلى تعديل؟</label><textarea name="request" rows="5" required></textarea></div>',async f=>{await api('/api/portal/'+p.id+'/revisions',{method:'POST',body:JSON.stringify({version_id:v.id,option_id:selectedOption?.id||null,request:f.get('request')})});clientPortalRefresh()},'إرسال طلب التعديل');$('#client-approve').onclick=async()=>{if(!confirm('هل أنت متأكد من اعتماد هذه النسخة؟'))return;try{await api('/api/portal/'+p.id+'/approve',{method:'POST',body:JSON.stringify({version_id:v.id,option_id:v.options?.find(o=>o.status==='SELECTED')?.id||null})});toast('تم اعتماد التصميم');clientPortalRefresh()}catch(x){toast(x.message,'error')}}}openStream('/api/portal/'+p.id+'/stream',x=>{if(x.type==='message')appendMessage(x.message);else if(['version','revision','approved','file','status','option'].includes(x.type))clientPortalRefresh()});state.syncTimer=setInterval(async()=>{try{const fresh=await api('/api/portal/'+p.id),old=state.portalData?.project?.updated_at;if(fresh.project.updated_at!==old){state.portalData=fresh;clientPortalView()}}catch{}} ,10000)}function clientPreview(files,n){const f=files.find(x=>x.mime.startsWith('image/')),url=f?'/api/portal/'+state.portalData.project.id+'/files/'+f.id:'';return f?`<a href="${url}" target="_blank" class="client-image-link"><img src="${url}" alt="التصميم V${n}"><span>فتح بالحجم الكامل ↗</span></a>`:'<div class="file-design-placeholder">اختر أحد خيارات التصميم لرؤية المعاينة<br><small>كل خيار له معاينة مستقلة</small></div>'}function clientFile(f){return`<div class="client-file"><span class="file-kind ${f.mime.startsWith('image/')?'image':'document'}">${f.mime.startsWith('image/')?'▧':'▤'}</span><span class="file-name"><b>${esc(f.original_name)}</b><small>${f.uploaded_by_type==='CLIENT'?'مرفق من طرفك':'مرفق من المصمم'} · ${Math.ceil(f.size/1024)} KB</small></span><a href="/api/portal/${state.portalData.project.id}/files/${f.id}" target="_blank">فتح</a></div>`}async function loadPortalMessages(){const ms=await api('/api/portal/'+state.portalData.project.id+'/messages');$('#messages').innerHTML='';ms.forEach(appendMessage)}function compareOptions(v,d){const opts=normalizeOptions(v.options||[],d.files.filter(f=>f.version_id===v.id));modal('مقارنة التصميمات',`<div class="compare-grid">${opts.map(o=>`<div class="compare-option"><h3>${esc(o.name)}</h3>${clientOptionPreview(d,o,d.files.filter(f=>f.version_id===v.id))}</div>`).join('')}</div>`,async()=>{},'إغلاق')}async function selectOption(id){try{await api('/api/portal/'+state.portalData.project.id+'/options/select',{method:'POST',body:JSON.stringify({version_id:state.portalData.versions[0].id,option_id:id})});toast('تم اختيار التصميم للمراجعة');clientPortalRefresh()}catch(e){toast(e.message,'error')}}function clientOptionPreview(d,o,files){return optionImage(o,true)}async function clientPortalRefresh(){const d=await api('/api/portal/'+state.portalData.project.id);state.portalData=d;clientPortalView()}async function logout(){closeStream();await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.user=null;login()}async function activityCenter(v){const q=new URLSearchParams();if(state.activityType)q.set('type',state.activityType);if(state.activitySearch)q.set('search',state.activitySearch);q.set('page',state.activityPage||1);const d=await api('/api/activity?'+q);const s=d.summary;v.innerHTML=pageHeader('المراقبة','مركز النشاط','سجل موحد لحركة المشاريع والتصميمات')+`<section class="kpi-grid activity-summary">${kpi('إجمالي الأحداث',s.total,'◌','purple')}${kpi('اليوم',s.today,'◷','gold')}${kpi('هذا الأسبوع',s.week,'◒','blue')}${kpi('طلبات التعديل',s.revisions,'✎','red')}${kpi('التصميمات المعتمدة',s.approvals,'✓','green')}</section><div class="activity-toolbar"><input class="search-input" placeholder="ابحث بالمشروع أو العميل أو الحدث" value="${esc(state.activitySearch||'')}" oninput="state.activitySearch=this.value;clearTimeout(window.activityTimer);window.activityTimer=setTimeout(()=>{state.activityPage=1;activityCenter($('#internal-view'))},350)"><div class="filter-chips"><button class="filter-chip ${!state.activityType?'active':''}" onclick="state.activityType='';activityCenter($('#internal-view'))">كل النشاط</button><button class="filter-chip ${state.activityType==='projects'?'active':''}" onclick="state.activityType='projects';activityCenter($('#internal-view'))">المشاريع</button><button class="filter-chip ${state.activityType==='designs'?'active':''}" onclick="state.activityType='designs';activityCenter($('#internal-view'))">التصميمات</button><button class="filter-chip ${state.activityType==='revisions'?'active':''}" onclick="state.activityType='revisions';activityCenter($('#internal-view'))">التعديلات</button><button class="filter-chip ${state.activityType==='approvals'?'active':''}" onclick="state.activityType='approvals';activityCenter($('#internal-view'))">الاعتمادات</button></div></div><section class="activity-feed panel">${d.events.length?activityCards(d.events):'<div class="empty-state"><h3>لا يوجد نشاط حتى الآن</h3><p>سيظهر هنا سجل حركة المشاريع والتصميمات.</p></div>'}<div class="pagination">${d.page>1?'<button class="btn btn-soft" onclick="state.activityPage--;activityCenter($(\'#internal-view\'))">السابق</button>':''}<span>صفحة ${d.page} من ${Math.max(1,d.pages)}</span>${d.page<d.pages?'<button class="btn btn-soft" onclick="state.activityPage++;activityCenter($(\'#internal-view\'))">التالي</button>':''}</div></section>`}function activityCards(events){const groups={};events.forEach(e=>{const key=new Date(e.created_at).toLocaleDateString('ar-SA',{dateStyle:'full'});(groups[key]??=[]).push(e)});return Object.entries(groups).map(([day,items])=>`<div class="activity-day"><h3>${day}</h3>${items.map(e=>`<button class="activity-card" onclick="openProject(${e.project_id})"><span class="activity-icon ${activityKind(e.action)}">${activityIcon(e.action)}</span><span class="activity-card-main"><b>${esc(e.action)}</b><strong>${esc(e.project_name)}</strong><small>${esc(e.details||'تم تحديث المشروع')} ${e.actor_name?'· بواسطة '+esc(e.actor_name):''}</small></span><time>${new Date(e.created_at).toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'})}</time><span>←</span></button>`).join('')}</div>`).join('')}function activityKind(a){return a==='اعتماد التصميم'?'approval':a==='طلب تعديل'?'revision':a==='رفع ملف'?'file':a==='إرسال رسالة'?'message':'design'}function activityIcon(a){return a==='اعتماد التصميم'?'✓':a==='طلب تعديل'?'✎':a==='رفع ملف'?'▧':a==='إرسال رسالة'?'◌':'◇'}async function designers2(v){const rows=await api('/api/designers?search='+encodeURIComponent(state.designerSearch||'')+(state.designerFilter?'&active='+state.designerFilter:''));const active=rows.filter(x=>x.active).length,projects=rows.reduce((n,x)=>n+(x.active_projects||0),0),approved=rows.reduce((n,x)=>n+(x.approved_projects||0),0);v.innerHTML=pageHeader('إدارة الفريق','المصممون','فريق التصميم الداخلي','<button class="btn btn-primary" onclick="newDesigner()">+ مصمم جديد</button>')+`<section class="kpi-grid designer-summary">${kpi('إجمالي المصممين',rows.length,'◉','purple')}${kpi('النشطون',active,'✓','green')}${kpi('المشاريع النشطة',projects,'◒','gold')}${kpi('التصميمات المعتمدة',approved,'◇','blue')}</section><div class="filter-bar"><input class="search-input" placeholder="ابحث بالاسم أو البريد أو الجوال" value="${esc(state.designerSearch||'')}" oninput="state.designerSearch=this.value;clearTimeout(window.designerTimer);window.designerTimer=setTimeout(()=>designers2($('#internal-view')),300)"><div class="filter-chips"><button class="filter-chip ${!state.designerFilter?'active':''}" onclick="state.designerFilter='';designers2($('#internal-view'))">الكل</button><button class="filter-chip ${state.designerFilter==='true'?'active':''}" onclick="state.designerFilter='true';designers2($('#internal-view'))">نشط</button><button class="filter-chip ${state.designerFilter==='false'?'active':''}" onclick="state.designerFilter='false';designers2($('#internal-view'))">غير نشط</button></div></div><section class="panel designer-list"><div class="table-head designer-head"><span>المصمم</span><span>الدخول</span><span>الحالة</span><span>المشاريع</span><span>المعتمدة</span><span>إجراءات</span></div>${rows.length?rows.map(d=>`<div class="table-row designer-row"><span class="table-project"><i class="project-avatar">${esc((d.name||'م').slice(0,1))}</i><span><b>${esc(d.name)}</b><small>${d.last_activity?'آخر نشاط '+ago(d.last_activity):'لا يوجد نشاط بعد'}</small></span></span><span>${esc(d.email||d.phone||'—')}</span><span>${d.active?'<span class="status status-approved"><i></i>نشط</span>':'<span class="status status-cancelled"><i></i>غير نشط</span>'}</span><span>${d.active_projects||0}</span><span>${d.approved_projects||0}</span><details class="action-menu"><summary aria-label="إجراءات المصمم">⋮</summary><div><button onclick="editDesigner(${d.id},'${esc(d.name)}','${esc(d.email||'')}','${esc(d.phone||'')}',${d.active})">تعديل البيانات</button><button onclick="toggleDesigner(${d.id},${d.active},${d.active_projects||0},'${esc(d.name)}')">${d.active?'تعطيل المصمم':'تفعيل المصمم'}</button><button class="danger-text" onclick="deleteDesigner(${d.id},'${esc(d.name)}')">حذف المصمم</button></div></details></div>`).join(''):'<div class="empty-state">لا يوجد مصممون بهذه المواصفات</div>'}</section>`}function editDesigner(id,name,email,phone,active){modal('تعديل بيانات المصمم',`<div class="field"><label>اسم المصمم</label><input name="name" value="${name}" required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" value="${email}"></div><div class="field"><label>رقم الجوال</label><input name="phone" value="${phone}"></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" placeholder="اتركها فارغة إذا لم ترد تغييرها"></div><div class="field"><label>الحالة</label><select name="active"><option value="true" ${active?'selected':''}>نشط</option><option value="false" ${!active?'selected':''}>غير نشط</option></select></div>`,async f=>{const b=Object.fromEntries(f);b.active=b.active==='true';return api('/api/designers/'+id,{method:'PATCH',body:JSON.stringify(b)})},'تحديث البيانات')}async function toggleDesigner(id,active,count,name){if(active&&count>0&&!confirm(`هذا المصمم لديه ${count} مشاريع نشطة. هل تريد تعطيله؟`))return;if(!active&&!confirm('هل تريد تفعيل هذا المصمم؟'))return;try{await api('/api/designers/'+id,{method:'PATCH',body:JSON.stringify({name,active:!active})});designers2($('#internal-view'))}catch(e){toast(e.message,'error')}}async function deleteDesigner(id,name){if(!confirm(`لا يمكن التراجع عن حذف المصمم ${name} إذا لم تكن لديه سجلات. هل تريد المتابعة؟`))return;try{await api('/api/designers/'+id,{method:'DELETE'});toast('تم حذف المصمم');designers2($('#internal-view'))}catch(e){toast(e.message,'error')}}render();
